// Tập 6 · C3 · phần chung của bốn đoạn N1 (hàng 10 thùng): dựng trang, cột "người + hàng thùng", khung khoá, lớp bắt buộc, nhãn, ngoặc.
// Mốc giờ chỉ từ spine.json của đoạn; hằng số ở đây = hình học + độ dài hiệu ứng chung.
import * as THREE from 'three';
import { Studio, Person, setOpacity } from '/toolkit/factory/world/lib3d.js';
import { Camera, Stage, loadJSON, fonts, C, ease } from '/toolkit/factory/world/core.js';
import { Crates, Check, checkScale } from '/episodes/ep006/world/obj6.js';

export const POP = 0.2, PLATE = '#0B0E13', FIG = '#C9D3E2';
export const kf = (k, t) => { if (!k || !k.length) return 1; if (t <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) if (t <= k[i][0]) { const [a, x] = k[i - 1], [b, y] = k[i]; return b > a ? x + (y - x) * (t - a) / (b - a) : y; }
  return k[k.length - 1][1]; };
// hiện từ mốc a (dốc POP), tắt từ mốc z (dốc 0,3 s) nếu có
export const show = (t, a, z = Infinity) => ease(t, a - 0.05, a + POP) * (1 - ease(t, z, z + 0.3));

export async function setup(seg, res, poses) {
  const [S, CL] = await Promise.all([loadJSON(seg + 'spine.json'), loadJSON('/episodes/ep006/world/claims.json')]);
  await fonts();
  const cue = {}; for (const b of S.beats) cue[b.id] = { ...b.cues, t0: b.t0, t1: b.t1 };
  const st = Stage(res), scene = new THREE.Scene(), { floor } = Studio(scene, { shadowBox: 18 });
  return { S, CL, cue, st, O: st.O, renderer: st.renderer, scene, floor, CAM: Camera(poses, S.moves) };
}

// cột (FIX-R2): [người][tấm séc][hàng 10 thùng] — người không mặt (W4, ILLUSTRATIVE) đứng bên trái tấm séc của mình, séc đứng ngay đầu trái
// hàng thùng nó mua: cùng một khung thấy séc lớn lên (1,02^k) trong khi thùng tối dần.
export function column(scene, { x, z = 0, size = 0.5, gap = 0.1, name, h = 1.45, cw = 0.48, cbase = 0.75 }) {
  const row = Crates({ size, gap, name }); row.position.set(x, 0, z); scene.add(row);
  const card = Check({ w: cw, base: cbase, name }); card.position.set(row.edgeX(0) - 0.18 - cw / 2, 0, z); scene.add(card);
  const person = Person({ h, color: FIG }); person.position.set(card.position.x - cw / 2 - 0.3, 0, z - 0.25); scene.add(person);
  person.userData.checks = { role: 'mark', char: name, key: 'person-' + name };
  return { row, card, person, x, z, h, size, name, cw, cbase };
}
// nhãn sự thật của tấm séc (chỉ chế độ đồ thị, claim two_pct_growth_20y_pct): đặt trên đỉnh séc ở năm 20, căn trái theo mép trái séc
export function checkLabel(O, col, CL, alpha, o = {}) {
  const [x, y] = O.toScreen(col.card.position.x - col.cw / 2, col.cbase * checkScale(20) + 0.06, col.z);
  return label(O, `check: +${CL.two_pct_growth_20y_pct.display} a year`, x + (o.dx || 0), y - 22, { kind: 'number', px: o.px || 48, alpha, ...o });
}
export const checkBox = (O, col) => { const [x0, y0] = O.toScreen(col.card.position.x - col.cw / 2 - 0.1, col.cbase * checkScale(20), col.z), [x1, y1] = O.toScreen(col.card.position.x + col.cw / 2 + 0.1, 0, col.z); return [x0 - 6, y0 - 6, x1 + 6, y1 + 6]; };
export function showColumn(col, a) { setOpacity(col.person, a); col.person.scale.setScalar(Math.max(0.001, 0.85 + 0.15 * a)); }
// tấm séc theo khung khoá k (số kỷ niệm) của spine: S.cards[tên] = [[t, k], …]; không có khoá → k = k0
export function setCheck(col, S, t, appear = 1, k0 = 0) { const K = (S.cards || {})[col.name]; return col.card.set({ k: K ? kf(K, t) : k0, appear }); }

// chế độ đồ thị: sàn + sương lùi đi (như Tập 5)
export function modeLook(scene, floor, cw) { floor.material.opacity = 1 - 0.85 * cw; scene.fog.near = 30 + 120 * cw; scene.fog.far = 80 + 220 * cw; }

// lớp bắt buộc: ILLUSTRATIVE (mọi khung có nhân vật), nguồn + "US only · history, not a forecast" (mọi khung lịch sử)
export function chrome(O) { O.chrome({ illus: true, src: 'US consumer prices (CPI-U)', hist: true }); }

// ngoặc ngang trên hàng thùng (ink-muted = cố định: "những gì khoản đầu mua"; ink = phần còn sáng) — nét lớp phủ, toạ độ thiết kế
export function brace(O, x0, x1, y, color, a, lw = 5, tick = 14) {
  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw;
  c.beginPath(); c.moveTo(x0, y + tick); c.lineTo(x0, y); c.lineTo(x1, y); c.lineTo(x1, y + tick); c.stroke(); c.restore();
}
export function label(O, s, x, y, o = {}) { return O.text(s, x, y, o.px || 52, { plate: PLATE, plateA: 0.72, ...o }); }
export { C };

"""Tập 6 · tiện ích chung cho các đoạn thế giới 3D (spine v2, D-010). Chỉ dùng take ĐÃ CÓ trong voice-takes/ (0 ký tự ElevenLabs).
  scene_take(sc)        → take của cảnh theo review-g1/voice-scenes.json (take commit của tập), kiểm chữ take == chữ kịch bản hiện tại
  scene_words(sc)       → từ (đã nói, có sid = câu kịch bản), đầu từ chỉnh theo năng lượng (onset.refine), giờ tính trong take
  episode_offsets()     → vị trí mỗi cảnh trong tập như nhà máy (take + đuôi 1,0 s; ident 3 s sau S03 như table_read.py)
  clip_voice(sids, lead)→ lời cho một đoạn ngắn (C3): cắt từ take theo câu (wav trong work/, không commit), từ đã dời giờ
Không gọi API: thiếu take → dừng (SystemExit)."""
import json, os, re, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
EP = os.path.dirname(HERE)
ROOT = os.path.abspath(os.path.join(EP, '..', '..'))
sys.path.insert(0, os.path.join(ROOT, 'toolkit', 'factory', 'world'))
sys.path.insert(0, os.path.join(ROOT, 'toolkit', 'factory'))
sys.dont_write_bytecode = True
from onset import refine  # noqa: E402
TAKES = os.path.join(EP, 'voice-takes')
LINE = re.compile(r'^(S\d\d)\.(\d+)\s+(?:\{(\w+)\}\s+)?(.+?)\s*<!--')
TAIL, IDENT_AFTER, IDENT = 1.0, 'S03', 3.0


def script_rows():
    out = []
    for ln in open(os.path.join(EP, 'story', 'script.md'), encoding='utf-8'):
        m = LINE.match(ln)
        if m: out.append({'id': f'{m.group(1)}.{m.group(2)}', 'scene': m.group(1), 'text': m.group(4).strip()})
    return out


def voice_scenes():
    return json.load(open(os.path.join(EP, 'review-g1', 'voice-scenes.json')))


def scene_take(sc):
    vs = voice_scenes()
    if sc not in vs: raise SystemExit(f'không có take cho {sc} trong voice-scenes.json — dừng (không sinh giọng)')
    h = vs[sc]['take'].replace('.mp3', '')
    mp3, js = os.path.join(TAKES, h + '.mp3'), os.path.join(TAKES, h + '.json')
    if not (os.path.exists(mp3) and os.path.exists(js)): raise SystemExit(f'take {h} của {sc} không có trong voice-takes/ — dừng')
    return h, mp3, json.load(open(js)), vs[sc]['duration']


_SPOKEN = {}


def spoken(rows):
    import voice as V                       # toolkit/factory/voice.py: chỉ dùng to_spoken (node, không mạng)
    key = tuple(r['text'] for r in rows)
    if key not in _SPOKEN: _SPOKEN[key] = V.to_spoken(list(key))
    return _SPOKEN[key]


def scene_words(sc, do_refine=True):
    h, mp3, meta, dur = scene_take(sc)
    rows = [r for r in script_rows() if r['scene'] == sc]
    sp = spoken(rows); text = ' '.join(sp)
    al = meta['alignment']
    if ''.join(al['characters']) != text or meta['text'] != text:
        raise SystemExit(f'{sc}: chữ take {h} khác chữ kịch bản hiện tại — dừng (cần đọc lại giọng)')
    st, en = al['character_start_times_seconds'], al['character_end_times_seconds']
    bounds, pos = [], 0
    for r, s in zip(rows, sp): bounds.append((r['id'], pos, pos + len(s))); pos += len(s) + 1
    words = []
    for m in re.finditer(r'\S+', text):
        sid = next(b[0] for b in bounds if b[1] <= m.start() < b[2])
        words.append({'w': m.group(0), 's': round(st[m.start()], 3), 'e': round(en[m.end() - 1], 3), 'sid': sid})
    if do_refine:
        words = refine(words, mp3)
    return {'hash': h, 'mp3': os.path.relpath(mp3, ROOT), 'duration': dur, 'words': words, 'lines': {r['id']: r['text'] for r in rows}}


def episode_offsets():
    """Vị trí đầu mỗi cảnh trong tập (giây) theo luật nhà máy: take + đuôi 1,0 s; ident 3 s sau S03 (table_read.py)."""
    vs, t, out = voice_scenes(), 0.0, {}
    for sc in sorted(vs):
        out[sc] = round(t, 3); t += vs[sc]['duration'] + TAIL + (IDENT if sc == IDENT_AFTER else 0)
    out['_end'] = round(t, 3)
    return out


def clip_voice(runs, lead=0.6, tail=0.25, pre=0.15, gap_same=0.6):
    """Lời cho một đoạn C3. runs = [[sid, sid…], …]: mỗi run là các câu LIỀN NHAU của một cảnh. Mỗi run: cắt take từ (đầu câu đầu − pre)
    tới (cuối câu cuối + tail) thành wav 48 kHz trong episodes/ep006/work/world-voice/ (không commit); run nối nhau cách 1,0 s
    (khác cảnh, như nhà máy) hoặc gap_same (cùng cảnh, bỏ câu giữa). Trả (words, takes, lines, end) — takes theo audio.py ({'wav', 't'})."""
    out_dir = os.path.join(EP, 'work', 'world-voice'); os.makedirs(out_dir, exist_ok=True)
    t, words, takes, lines, prev = lead, [], [], {}, None
    for ss in runs:
        sc = ss[0][:3]
        if prev is not None: t += TAIL if sc != prev else gap_same
        W = scene_words(sc)
        ws = [w for w in W['words'] if w['sid'] in ss]
        if not ws or ws[0]['sid'] != ss[0] or ws[-1]['sid'] != ss[-1]: raise SystemExit(f'câu {ss} không có trong take {sc}')
        a = max(0.0, float(min(w['s'] for w in ws)) - pre); b = float(max(w['e'] for w in ws)) + tail
        wav = os.path.join(out_dir, f"{W['hash']}-{a:.3f}-{b:.3f}.wav")
        if not os.path.exists(wav):
            subprocess.run(['ffmpeg', '-v', 'error', '-y', '-ss', f'{a:.3f}', '-to', f'{b:.3f}', '-i', os.path.join(ROOT, W['mp3']), '-ar', '48000', '-ac', '1',
                            '-af', 'afade=t=in:d=0.02,afade=t=out:st={:.3f}:d=0.03'.format(b - a - 0.03), wav], check=True)
        words += [{'w': w['w'], 's': round(float(w['s']) - a + t, 3), 'e': round(float(w['e']) - a + t, 3), 'sid': w['sid'],
                   's_tts': round(float(w['s_tts']) - a + t, 3)} for w in ws]
        takes.append({'wav': os.path.relpath(wav, ROOT), 'mp3': W['mp3'], 'take': W['hash'], 'from': round(a, 3), 'to': round(b, 3), 't': round(t, 3)})
        lines.update({s: W['lines'][s] for s in ss})
        t += b - a; prev = sc
    return words, takes, lines, round(t, 3)


def music_plan_flat(total, accents):
    """Đoạn C3 ngắn: nhạc không tắt giữa đoạn (stop = cuối), điểm nhấn felt ở các mốc dữ liệu."""
    return {'stop': total, 'tau': 0.25, 'release': total + 1.0, 'accents': accents[:4]}

content.content:
1	// Tập 6 · VẬT THỂ MỚI (C3, D-010 quy tắc 4) — chưa vào lib3d.js (không sửa toolkit trong phiên này). Gen kênh: low-poly, màu kênh (E2 tokens.json).
2	//  N1 Crates — hàng 10 thùng = những gì khoản trả ĐẦU TIÊN của nhân vật mua được. value = sức mua hiện tại so với khoản đầu (0 … ≥ 1).
3	//  Thùng i (0-based) sáng theo PHẦN: b_i = clamp(n·value − i, 0, 1) — mờ liên tục, không làm tròn nguyên (REVIEW-C2v3 PHỤ-4):
4	//  0,904 → 9 thùng sáng đủ + thùng thứ 10 sáng 4 %. value ≥ 1 → 10 sáng đủ, KHÔNG BAO GIỜ quá n (PHỤ-5: Edna 105,7 % vẫn là 10).
5	//  Thùng tối = ink-muted sẫm (không biến mất). Không chữ, không nhãn, không dáng thực phẩm/tiền: khối hộp + nắp + một nẹp ngang.
6	import * as THREE from 'three';
7	
8	export const CRATE = { lit: '#F2F4F7', dark: '#3E444D', slat: '#2A303B', glow: '#F2F4F7' };   // ink · ink-muted sẫm · grid (E2)
9	export const litOf = (value, n = 10) => Math.min(n, Math.max(0, n * value));                   // số thùng sáng (thực, có phần lẻ)
10	
11	const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
12	
13	// ---------------------------------------------------------------- N1 hàng thùng (gốc toạ độ = tâm hàng, đáy trên sàn y = 0, mặt trước hướng +z)
14	export function Crates({ n = 10, size = 0.5, gap = 0.1, name = 'row' } = {}) {
15	  const g = new THREE.Group(), pitch = size + gap, W = n * pitch - gap, h = size * 0.78, d = size * 0.8;
16	  const body = new THREE.BoxGeometry(size, h, d), lid = new THREE.BoxGeometry(size * 1.04, size * 0.07, d * 1.04), slat = new THREE.BoxGeometry(size * 1.005, size * 0.05, 0.01);
17	  const lit = new THREE.Color(CRATE.lit), dark = new THREE.Color(CRATE.dark), crates = [];
18	  for (let i = 0; i < n; i++) {
19	    const c = new THREE.Group(), m = mat(CRATE.dark, { emissive: new THREE.Color(CRATE.glow), emissiveIntensity: 0 });
20	    const b = new THREE.Mesh(body, m); b.position.y = h / 2; b.castShadow = b.receiveShadow = true;
21	    const l = new THREE.Mesh(lid, m); l.position.y = h + size * 0.035; l.castShadow = true;
22	    const s = new THREE.Mesh(slat, mat(CRATE.slat)); s.position.set(0, h * 0.5, d / 2 + 0.006);
23	    c.add(b, l, s); c.position.x = -W / 2 + size / 2 + i * pitch;
24	    c.userData.checks = { role: 'mark', series: name, key: `crate-${name}-${i}` };
25	    g.add(c); crates.push({ c, m, s });
26	  }
27	  g.userData = { n, size, pitch, width: W, height: h + size * 0.07, crates };
28	  // value: sức mua so khoản đầu (0 … ≥ 1); appear ∈ [0,1]: thùng mọc lên từ sàn lần lượt trái → phải; pulse ∈ [0,1]: loé nhẹ các thùng đang sáng
