1	// Mốc V · THƯ VIỆN VẬT THỂ 3D CÓ THAM SỐ (D-010 §2 quy tắc 4) — dựng một lần, mọi tập dùng lại.
2	// Gen kênh (D-010 §3): thế giới 3D tối giản — low-poly, màu kênh, không chân thực ảnh, nhân vật không mặt, không chi tiết trang trí vô nghĩa.
3	// Đơn vị: trục y = đô la theo thang của cảnh (UNIT_USD / đơn vị); bó tiền có MỆNH GIÁ CỐ ĐỊNH (BUNDLE_USD) nên chiều cao chồng = số bó × độ dày bó.
4	// Mọi vật là hàm thuần của tham số; cảnh gọi .set(...) mỗi khung (không đồng hồ, không ngẫu nhiên không hạt).
5	// W1–W10: visual-library §5 (W10 Crates + Check cuối file, F-12).
6	import * as THREE from 'three';
7	
8	export const PALETTE = { bg: '#0E1116', surface: '#171B22', grid: '#2A303B', ink: '#F2F4F7', muted: '#9AA4B2', accent: '#4C8DFF',
9	  warn: '#F2B441', costlier: '#C72323', cushion: '#269783',
10	  // màu vật liệu (không phải màu dữ liệu): tường, mái, tiền, sàn
11	  wall: '#D9D4C7', roof: '#8A4B3A', bill: '#5E8C6A', bill2: '#4E7A5A', strap: '#E9E3D3', floor: '#161B23', person1: '#E2D3C2', person2: '#C9D3E2' };
12	
13	const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.85, transparent: true, ...o });
14	export function setOpacity(obj, a) { obj.traverse((o) => { if (o.isMesh) for (const m of [].concat(o.material)) { m.opacity = a; m.depthWrite = a > 0.98; } o.visible = a > 0.005; }); }
15	
16	// ---------------------------------------------------------------- nhà (một tầng, mái dốc, cửa sổ sáng)
17	export function House({ w = 1.6, wall = PALETTE.wall, roof = PALETTE.roof, lit = true } = {}) {
18	  const g = new THREE.Group(), d = w * 0.72, h = w * 0.6, rh = w * 0.45;
19	  const add = (m, x, y, z) => { m.position.set(x, y, z); m.castShadow = m.receiveShadow = true; g.add(m); return m; };
20	  add(new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(wall)), 0, h / 2, 0);
21	  const s = new THREE.Shape(); s.moveTo(-w / 2 - w * 0.06, 0); s.lineTo(w / 2 + w * 0.06, 0); s.lineTo(0, rh); s.closePath();
22	  add(new THREE.Mesh(new THREE.ExtrudeGeometry(s, { depth: d + w * 0.15, bevelEnabled: false }), mat(roof, { roughness: 0.7 })), 0, h, -d / 2 - w * 0.075);
23	  const win = mat('#2B2F38', { emissive: new THREE.Color('#F6D58E'), emissiveIntensity: lit ? 0.9 : 0, roughness: 0.3 });
24	  for (const x of [-w * 0.29, w * 0.29]) add(new THREE.Mesh(new THREE.BoxGeometry(w * 0.17, h * 0.3, 0.03), win), x, h * 0.58, d / 2 + 0.02);
25	  add(new THREE.Mesh(new THREE.BoxGeometry(w * 0.16, h * 0.52, 0.04), mat('#3B4A5A')), 0, h * 0.26, d / 2 + 0.02);
26	  g.userData.height = h + rh;
27	  return g;
28	}
29	
30	// ---------------------------------------------------------------- chồng tiền: bó mệnh giá cố định; .set({usd, warnAboveUsd, tintBelowUsd, tint})
31	export function Stack({ unitUsd = 1e5, bundleUsd = 25000, w = 1.1, d = 0.7, maxUsd = 1.2e6 } = {}) {
32	  const n = Math.ceil(maxUsd / bundleUsd), th = bundleUsd / unitUsd;
33	  const geo = new THREE.BoxGeometry(w, th * 0.92, d), m = new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true });
34	  const mesh = new THREE.InstancedMesh(geo, m, n); mesh.castShadow = mesh.receiveShadow = true;
35	  const strapG = new THREE.BoxGeometry(w * 0.16, th * 0.94, d * 1.02), strap = new THREE.InstancedMesh(strapG, mat(PALETTE.strap), n);
36	  mesh.frustumCulled = strap.frustumCulled = false;   // vùng bao của InstancedMesh bị cache ở khung đầu (mọi bó ẩn) → chồng bị loại sai khi đáy ra ngoài khung
37	  const g = new THREE.Group(); g.add(mesh, strap);
38	  const M = new THREE.Matrix4(), col = new THREE.Color(), hide = new THREE.Matrix4().makeScale(0, 0, 0);
39	  g.userData = { bundleUsd, unitUsd, th, n };
40	  g.set = ({ usd = 0, fromUsd = 0, warnAboveUsd = Infinity, tintBelowUsd = 0, tint = PALETTE.cushion, tintA = 1 } = {}) => {
41	    const k0 = Math.floor(fromUsd / bundleUsd), k1 = usd / bundleUsd;
42	    for (let k = 0; k < n; k++) {
43	      const frac = Math.min(1, Math.max(0, k1 - k));
44	      if (k < k0 || frac <= 0.001) { mesh.setMatrixAt(k, hide); strap.setMatrixAt(k, hide); continue; }
45	      const y = (k - k0) * th + th * frac / 2;
46	      M.makeScale(1, frac, 1).setPosition(0, y, 0);
47	      mesh.setMatrixAt(k, M); strap.setMatrixAt(k, M);
48	      const usdK = (k + 0.5) * bundleUsd;
49	      if (usdK > warnAboveUsd) col.set(PALETTE.warn);
50	      else if (usdK < tintBelowUsd) col.set(PALETTE.bill).lerp(new THREE.Color(tint), tintA);
51	      else col.set(k % 2 ? PALETTE.bill : PALETTE.bill2);
52	      mesh.setColorAt(k, col);
53	    }
54	    mesh.instanceMatrix.needsUpdate = strap.instanceMatrix.needsUpdate = true; if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
55	    return Math.max(0, (k1 - k0)) * th;   // chiều cao thế giới
56	  };
57	  return g;
58	}
59	
60	// ---------------------------------------------------------------- xà trần / vạch cố định (thanh kính-thép dài theo trục thời gian)
61	export function Beam({ length = 15, color = PALETTE.muted } = {}) {
62	  const g = new THREE.Group();
63	  const core = new THREE.Mesh(new THREE.BoxGeometry(length, 0.07, 0.07), mat(color, { emissive: new THREE.Color(color), emissiveIntensity: 0.35 }));
64	  const glass = new THREE.Mesh(new THREE.BoxGeometry(length, 0.1, 0.4), mat('#AFC3D9', { opacity: 0.14, roughness: 0.1, metalness: 0.2 }));
65	  g.add(glass, core); g.userData = { core, glass };
66	  g.glow = (a, c = PALETTE.warn) => { core.material.emissive.set(a > 0 ? c : color); core.material.emissiveIntensity = 0.35 + 1.2 * a; core.material.color.set(a > 0.5 ? c : color); };
67	  return g;
68	}
69	
70	// ---------------------------------------------------------------- người minh hoạ không mặt (đầu cầu + thân viên nang)
71	export function Person({ h = 1.0, color = PALETTE.person1 } = {}) {
72	  const g = new THREE.Group(), m = mat(color, { roughness: 0.9 });
73	  const body = new THREE.Mesh(new THREE.CapsuleGeometry(h * 0.16, h * 0.42, 4, 10), m); body.position.y = h * 0.39; body.castShadow = true;
74	  const head = new THREE.Mesh(new THREE.SphereGeometry(h * 0.13, 16, 12), m); head.position.y = h * 0.86; head.castShadow = true;
75	  g.add(body, head); return g;
76	}
77	
78	// ---------------------------------------------------------------- khu phố tối giản: n nhà nhỏ + biển SOLD (không chữ: biển trắng–đỏ)
79	export function Neighborhood({ n = 12, seed = 7, spanX = [-6, 6], z = -3.5, size = 0.55 } = {}) {
80	  let s = seed >>> 0; const R = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
81	  const g = new THREE.Group(), items = [];
82	  for (let k = 0; k < n; k++) {
83	    const hs = House({ w: size * (0.85 + 0.3 * R()), wall: '#B8BFCA', roof: '#5F6B7A', lit: false });
84	    const sign = new THREE.Group();
85	    const post = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.4, 0.03), mat('#8C8C88')); post.position.y = 0.2;
86	    const plate = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.16, 0.02), mat('#F4F1EA')); plate.position.y = 0.42;
87	    const band = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.05, 0.025), mat(PALETTE.costlier)); band.position.y = 0.42;
88	    sign.add(post, plate, band); sign.position.set(size * 0.7, 0, size * 0.5);
89	    const it = new THREE.Group(); it.add(hs, sign);
90	    it.position.set(spanX[0] + (spanX[1] - spanX[0]) * (k + 0.5) / n + (R() - 0.5) * 0.3, 0, z + (R() - 0.5) * 1.6);
91	    g.add(it); items.push({ it, sign, home: it.position.clone() });
92	  }
93	  g.userData.items = items; return g;
94	}
95	
96	// ---------------------------------------------------------------- dải đường dữ liệu (ribbon phẳng ở z cố định, nhìn rõ ở cả hai chế độ)
97	export function Ribbon({ maxPts = 600, width = 0.09, color = PALETTE.ink, z = 0.45 } = {}) {
98	  const geo = new THREE.BufferGeometry(), pos = new Float32Array(maxPts * 2 * 3), colA = new Float32Array(maxPts * 2 * 3);
99	  const idx = []; for (let i = 0; i < maxPts - 1; i++) { const a = 2 * i; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
100	  geo.setIndex(idx); geo.setAttribute('position', new THREE.BufferAttribute(pos, 3)); geo.setAttribute('color', new THREE.BufferAttribute(colA, 3));
101	  const m = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, side: THREE.DoubleSide, depthWrite: false });
102	  const mesh = new THREE.Mesh(geo, m); mesh.frustumCulled = false; mesh.renderOrder = 5;
103	  const c = new THREE.Color();
104	  // pts: [[x, y, colorHex?], ...]; width in world units
105	  mesh.set = (pts, w = width, col = color) => {
106	    const n = Math.min(pts.length, maxPts);
107	    for (let i = 0; i < n; i++) {
108	      const p = pts[i], q0 = pts[Math.max(0, i - 1)], q1 = pts[Math.min(n - 1, i + 1)];
109	      let dx = q1[0] - q0[0], dy = q1[1] - q0[1]; const L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
110	      const nx = -dy * w / 2, ny = dx * w / 2;
111	      pos.set([p[0] + nx, p[1] + ny, z, p[0] - nx, p[1] - ny, z], 6 * i);
112	      c.set(p[2] || col); colA.set([c.r, c.g, c.b, c.r, c.g, c.b], 6 * i);
113	    }
114	    geo.setDrawRange(0, Math.max(0, (n - 1) * 6));
115	    geo.attributes.position.needsUpdate = geo.attributes.color.needsUpdate = true;
116	  };
117	  return mesh;
118	}
119	
120	// ---------------------------------------------------------------- sàn + ánh sáng studio (mặc định của kênh)
121	export function Studio(scene, { shadowBox = 14 } = {}) {
122	  scene.background = new THREE.Color(PALETTE.bg);
123	  scene.fog = new THREE.Fog(PALETTE.bg, 30, 80);
124	  scene.add(new THREE.HemisphereLight('#C9D6EA', '#1A1F27', 0.9));
125	  const key = new THREE.DirectionalLight('#FFF1DC', 2.3); key.position.set(-6, 14, 10); key.castShadow = true;
126	  key.shadow.mapSize.set(1024, 1024); Object.assign(key.shadow.camera, { left: -shadowBox, right: shadowBox, top: shadowBox, bottom: -4, near: 1, far: 50 });
127	  key.shadow.bias = -0.0008; key.target.position.set(0, 3, 0); scene.add(key, key.target);
128	  const rim = new THREE.DirectionalLight('#8FB4FF', 0.6); rim.position.set(6, 6, -10); scene.add(rim);
129	  const floor = new THREE.Mesh(new THREE.PlaneGeometry(160, 160), new THREE.MeshStandardMaterial({ color: PALETTE.floor, roughness: 0.95, transparent: true }));
130	  floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true; floor.userData.role = 'bg'; scene.add(floor);   // 'bg': lớp 'graphics' của trang kiểm bỏ sàn
131	  return { key, rim, floor };
132	}
133	
134	// ---------------------------------------------------------------- tia loé (sprite) ở một điểm sự kiện
135	export function Burst({ color = PALETTE.warn } = {}) {
136	  const cv = document.createElement('canvas'); cv.width = cv.height = 128;
137	  const g = cv.getContext('2d'), gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
138	  gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(0.3, 'rgba(255,255,255,0.5)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
139	  g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
140	  const t = new THREE.CanvasTexture(cv);
141	  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: t, color, transparent: true, depthWrite: false })); s.renderOrder = 9;
142	  return s;
143	}
144	
145	// ---------------------------------------------------------------- căn hộ thuê (khối nhiều tầng tối giản) — vật thể mới Tập 5 (E4: duyệt qua clip)
146	export function Apartment({ w = 1.6, floors = 4, color = '#8E99A8' } = {}) {
147	  const g = new THREE.Group(), fh = 0.5, d = w * 0.7;
148	  const body = new THREE.Mesh(new THREE.BoxGeometry(w, fh * floors, d), mat(color)); body.position.y = fh * floors / 2; body.castShadow = body.receiveShadow = true; g.add(body);
149	  const win = mat('#2B2F38', { emissive: new THREE.Color('#F6D58E'), emissiveIntensity: 0.6 });
150	  for (let f = 0; f < floors; f++) for (const x of [-w * 0.3, 0, w * 0.3]) { const m = new THREE.Mesh(new THREE.BoxGeometry(w * 0.16, fh * 0.42, 0.03), win); m.position.set(x, fh * (f + 0.55), d / 2 + 0.02); g.add(m); }
151	  g.userData.height = fh * floors; return g;
152	}
153	
154	// ---------------------------------------------------------------- thẻ bảo hiểm (khiên phẳng) gắn lên mái — vật thể mới Tập 5 (E4)
155	export function Shield({ size = 0.7, color = PALETTE.warn } = {}) {
156	  const s = new THREE.Shape(), r = size / 2;
157	  s.moveTo(0, r); s.lineTo(r * 0.9, r * 0.7); s.lineTo(r * 0.8, -r * 0.2); s.quadraticCurveTo(r * 0.5, -r * 0.8, 0, -r); s.quadraticCurveTo(-r * 0.5, -r * 0.8, -r * 0.8, -r * 0.2); s.lineTo(-r * 0.9, r * 0.7); s.closePath();
158	  const m = new THREE.Mesh(new THREE.ExtrudeGeometry(s, { depth: 0.08, bevelEnabled: true, bevelSize: 0.02, bevelThickness: 0.02, bevelSegments: 1 }), mat(color, { emissive: new THREE.Color(color), emissiveIntensity: 0.25 }));
159	  m.castShadow = true; const g = new THREE.Group(); g.add(m); return g;
160	}
161	
162	// ---------------------------------------------------------------- bó đường mảnh (nhiều đường lịch sử, 1 px) — "phát lại" nhiều tháng mua
163	export function Fan({ maxSeg = 60000 } = {}) {
164	  const geo = new THREE.BufferGeometry(), pos = new Float32Array(maxSeg * 2 * 3), col = new Float32Array(maxSeg * 2 * 3);
165	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3)); geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
166	  const mesh = new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false })); mesh.frustumCulled = false; mesh.renderOrder = 4;
167	  const c = new THREE.Color();
168	  mesh.set = (lines, z = 0.3) => {   // lines: [{pts:[[x,y],...], color}], vẽ hết những gì được đưa vào
169	    let n = 0;
170	    for (const L of lines) { c.set(L.color); for (let i = 1; i < L.pts.length && n < maxSeg; i++, n++) {
171	      pos.set([L.pts[i - 1][0], L.pts[i - 1][1], z, L.pts[i][0], L.pts[i][1], z], 6 * n); col.set([c.r, c.g, c.b, c.r, c.g, c.b], 6 * n); } }
172	    geo.setDrawRange(0, 2 * n); geo.attributes.position.needsUpdate = geo.attributes.color.needsUpdate = true;
173	  };
174	  return mesh;
175	}
176	
177	// ================================================================ W10 (Tập 6 C3, chủ dự án duyệt 08/10; BACKLOG F-12 c) — chuyển nguyên từ episodes/ep006/world/obj6.js
178	//  Crates — hàng n thùng = những gì khoản trả ĐẦU TIÊN của nhân vật mua được. value = sức mua hiện tại so với khoản đầu (0 … ≥ 1).
179	//  Thùng i (0-based) sáng theo PHẦN: b_i = clamp(n·value − i, 0, 1) — mờ liên tục, không làm tròn nguyên:
180	//  0,904 → 9 thùng sáng đủ + thùng thứ 10 sáng 4 %. value ≥ 1 → n sáng đủ, KHÔNG BAO GIỜ quá n (105,7 % vẫn là 10).
181	//  Thùng tối = ink-muted sẫm (không biến mất). Không chữ, không nhãn, không dáng thực phẩm/tiền: khối hộp + nắp + một nẹp ngang.
182	//  Check — tấm séc lớn lên base·1,02^k cạnh hàng thùng (không dùng hàng thùng một mình: vòng 1 không séc → người đọc hiểu "khoản đều").
183	//  Vật liệu roughness 0,8 (mat8) như bản đã duyệt — khác mat() 0,85 của các vật khác, giữ để khung trùng bản C3.
184	const mat8 = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
185	export const CRATE = { lit: '#F2F4F7', dark: '#3E444D', slat: '#2A303B', glow: '#F2F4F7' };   // ink · ink-muted sẫm · grid (E2)
186	export const litOf = (value, n = 10) => Math.min(n, Math.max(0, n * value));                   // số thùng sáng (thực, có phần lẻ)
187	
188	// ---------------------------------------------------------------- W10 hàng thùng (gốc toạ độ = tâm hàng, đáy trên sàn y = 0, mặt trước hướng +z)
189	export function Crates({ n = 10, size = 0.5, gap = 0.1, name = 'row' } = {}) {
190	  const g = new THREE.Group(), pitch = size + gap, W = n * pitch - gap, h = size * 0.78, d = size * 0.8;
191	  const body = new THREE.BoxGeometry(size, h, d), lid = new THREE.BoxGeometry(size * 1.04, size * 0.07, d * 1.04), slat = new THREE.BoxGeometry(size * 1.005, size * 0.05, 0.01);
192	  const lit = new THREE.Color(CRATE.lit), dark = new THREE.Color(CRATE.dark), crates = [];
193	  for (let i = 0; i < n; i++) {
194	    const c = new THREE.Group(), m = mat8(CRATE.dark, { emissive: new THREE.Color(CRATE.glow), emissiveIntensity: 0 });
195	    const b = new THREE.Mesh(body, m); b.position.y = h / 2; b.castShadow = b.receiveShadow = true;
196	    const l = new THREE.Mesh(lid, m); l.position.y = h + size * 0.035; l.castShadow = true;
197	    const s = new THREE.Mesh(slat, mat8(CRATE.slat)); s.position.set(0, h * 0.5, d / 2 + 0.006);
198	    c.add(b, l, s); c.position.x = -W / 2 + size / 2 + i * pitch;
199	    c.userData.checks = { role: 'mark', series: name, key: `crate-${name}-${i}` };
200	    g.add(c); crates.push({ c, m, s });
201	  }
202	  g.userData = { n, size, pitch, width: W, height: h + size * 0.07, crates };
203	  // value: sức mua so khoản đầu (0 … ≥ 1); appear ∈ [0,1]: thùng mọc lên từ sàn lần lượt trái → phải; pulse ∈ [0,1]: loé nhẹ các thùng đang sáng
204	  g.set = ({ value = 1, appear = 1, pulse = 0 } = {}) => {
205	    const L = litOf(value, n);
206	    for (let i = 0; i < n; i++) {
207	      const { c, m, s } = crates[i], bi = Math.min(1, Math.max(0, L - i));
208	      m.color.copy(dark).lerp(lit, bi); m.emissiveIntensity = bi * (0.32 + 0.35 * pulse);
209	      const a = Math.min(1, Math.max(0, appear * (1 + 0.3 * (n - 1)) - i * 0.3));   // mọc lần lượt, hàng đầy khi appear = 1
210	      c.scale.set(1, Math.max(0.001, a), 1); c.visible = a > 0.002;
211	      for (const q of [m, s.material]) { q.opacity = Math.min(1, a * 1.5); q.depthWrite = a > 0.98; }
212	      c.userData.checks.level = +bi.toFixed(3);
213	    }
214	    return L;
215	  };
216	  // toạ độ thế giới (cục bộ → thế giới) của mép trái/phải và tâm thùng i — cho nhãn và ngoặc ở lớp phủ
217	  g.crateX = (i) => g.position.x - W / 2 + size / 2 + i * pitch;
218	  g.edgeX = (f) => g.position.x - W / 2 + f * pitch - (f >= n ? gap : 0);   // f = số thùng (thực) tính từ trái
219	  g.set({ value: 1, appear: 1 });
220	  return g;
221	}
222	
223	// ---------------------------------------------------------------- W10b Check — tấm séc của nhân vật (FIX-R2 Tập 6, D-009 E6: sửa bằng hình, không nhãn khuyên)
224	//  Thẻ đứng low-poly màu ink (vai "tấm séc tăng dần", beats.md Colour roles) + hai vạch grid trừu tượng (không ký hiệu/chữ số tiền).
225	//  Chiều cao = base·1,02^k (k = số kỷ niệm đã qua, 0 … 20 → ×1,486): séc LỚN LÊN mỗi năm, cạnh hàng thùng đang tối dần.
226	//  Vạch ngang ink-muted CỐ ĐỊNH ở chiều cao khoản đầu (rộng hơn thẻ) = "khoản đầu" để thấy phần séc đã vượt lên.
227	//  Gốc toạ độ = tâm đáy thẻ trên sàn, mặt trước hướng +z.
228	export const CHECK = { card: '#F2F4F7', line: '#2A303B', first: '#9AA4B2', rate: 1.02 };
229	export const checkScale = (k) => Math.pow(CHECK.rate, Math.max(0, k));
230	export function Check({ w = 0.42, base = 0.6, d = 0.05, name = 'check' } = {}) {
231	  const g = new THREE.Group(), inner = new THREE.Group();
232	  const m = mat8(CHECK.card, { emissive: new THREE.Color(CHECK.card), emissiveIntensity: 0.3 });
233	  const body = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), m); body.position.y = 0.5; body.castShadow = body.receiveShadow = true;
234	  const ln = mat8(CHECK.line), lines = [0.7, 0.52].map((f, j) => {
235	    const s = new THREE.Mesh(new THREE.BoxGeometry(w * (j ? 0.45 : 0.62), 0.035, 0.01), ln); s.position.set(-w * (j ? 0.18 : 0.1), f, d / 2 + 0.006); return s; });
236	  inner.add(body, ...lines); g.add(inner);
237	  const fm = mat8(CHECK.first), first = new THREE.Mesh(new THREE.BoxGeometry(w + 0.2, 0.04, 0.02), fm); first.position.set(0, base, d / 2 + 0.02);
238	  g.add(first);
239	  g.userData = { w, base, d, inner, first, checks: { role: 'mark', series: name, key: `check-${name}` } };
240	  // k: số kỷ niệm (thực, có thể lẻ); appear ∈ [0,1]: thẻ mọc từ sàn + hiện dần
241	  g.set = ({ k = 0, appear = 1 } = {}) => {
242	    const s = checkScale(k), a = Math.min(1, Math.max(0, appear));
243	    inner.scale.set(1, Math.max(0.001, base * s * a), 1);
244	    for (const q of [m, ln, fm]) { q.opacity = Math.min(1, a * 1.5); q.depthWrite = a > 0.98; }
245	    g.visible = a > 0.002; first.visible = a > 0.5;
246	    g.userData.checks.level = +s.toFixed(4);
247	    return s;
248	  };
249	  g.set({ k: 0 });
250	  return g;
251	}
