349	}
350	export function roundRect(ctx, x, y, w, h, r) { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }
351	
352	// ------------------------------------------------------------------ máy quay: chụp / đặt lại trạng thái (freeze của trang kiểm)
353	const grabCam = (c) => ({ pos: c.position.toArray(), quat: c.quaternion.toArray(), fov: c.fov, aspect: c.aspect, near: c.near, far: c.far, zoom: c.zoom });
354	function applyCam(c, s) { c.position.fromArray(s.pos); c.quaternion.fromArray(s.quat); Object.assign(c, { fov: s.fov, aspect: s.aspect, near: s.near, far: s.far, zoom: s.zoom }); c.updateProjectionMatrix(); c.updateMatrixWorld(true); }
355	// vật 3D khai cho trang kiểm: object.userData.checks = {role, case?, year?, series?, …} → hình hộp bao chiếu lên màn hình (thiết kế 1920×1080)
356	const _b = new THREE.Box3(), _v = new THREE.Vector3();
357	function shapes3d(scene, cam) {
358	  const out = [];
359	  scene.traverse((o) => {
360	    const k = o.userData && o.userData.checks; if (!k || !o.visible) return;
361	    _b.setFromObject(o); if (_b.isEmpty()) return;
362	    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity, op = 0;
363	    for (let i = 0; i < 8; i++) { _v.set(i & 1 ? _b.max.x : _b.min.x, i & 2 ? _b.max.y : _b.min.y, i & 4 ? _b.max.z : _b.min.z).project(cam);
364	      const x = (_v.x + 1) * 960, y = (1 - _v.y) * 540; x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
365	    o.traverse((m) => { if (m.isMesh && m.visible) for (const q of [].concat(m.material)) op = Math.max(op, q.opacity ?? 1); });
366	    const box = [x0, y0, x1, y1].map(r1), key = k.key || o.name || o.uuid;
367	    out.push({ kind: 'shape', tag: 'mesh', role: 'mark', fill: null, stroke: null, ...k, box, opacity: +op.toFixed(3), key, sig: `${k.role || 'mark'}|${key}|${box.map(Math.round)}` });
368	  });
369	  return out;
370	}
371	
372	// ------------------------------------------------------------------ khởi tạo trang chung: renderer WebGL + lớp phủ + canvas ra
373	export function Stage(res) {
374	  const V = CK.view && CK.view.orient === 'v' ? CK.view : null;
375	  const W = V ? Math.round(1080 * res / 1920) : Math.round(1920 * res / 1080), H = res;
376	  const vs = V ? (V.s || 1) : 1, cy = V ? (V.cy ?? (VZONE.y0 + VZONE.y1) / 2) : 0;
377	  const gl = document.createElement('canvas');
378	  // alpha: true — nền là scene.background (đục) nên khung render như cũ; lớp 'graphics' của trang kiểm cần nền trong suốt
379	  const renderer = new THREE.WebGLRenderer({ canvas: gl, antialias: true, preserveDrawingBuffer: true, powerPreference: 'low-power', alpha: true });
380	  renderer.setPixelRatio(1); renderer.setSize(W, H, false);
381	  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFShadowMap;
382	  renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.05; renderer.outputColorSpace = THREE.SRGBColorSpace;
383	  const ov = document.createElement('canvas'), out = document.createElement('canvas'); out.width = W; out.height = H; document.body.appendChild(out);
384	  const O = Overlay(ov, res), octx = out.getContext('2d', CK.dither >= 2 ? { willReadFrequently: true } : undefined);
385	  const render0 = renderer.render.bind(renderer), cc = new THREE.Color();
386	  renderer.render = (scene, cam) => {
387	    const m = CK.mode;
388	    if (CK.dither >= 1) scene.traverse((o) => { if (o.material) for (const q of [].concat(o.material)) if (!q.dithering) { q.dithering = true; q.needsUpdate = true; } });
389	    if (CK.freezeCam) applyCam(cam, CK.freezeCam); else CK.lastCam = grabCam(cam);
390	    if (CK.on && m === 'all') CK.shapes3d = shapes3d(scene, cam);
391	    if (V) cam.setViewOffset(1920, 1080, 960 - 540 / vs, 540 - cy / vs, 1080 / vs, 1920 / vs);   // cửa sổ dọc của cùng khung thiết kế
392	    if (m === 'text' || m === 'glyph' || m === 'only' || m === 'graphics2d') { renderer.getClearColor(cc); const ca = renderer.getClearAlpha(); renderer.setClearColor(0x000000, 0); renderer.clear(); renderer.setClearColor(cc, ca); }
393	    else if (m === 'graphics' || m === 'graphics3d') {   // không nền: scene.background, sàn (userData.role 'bg')
394	      const bg = scene.background, hid = []; scene.background = null;
395	      scene.traverse((o) => { if (o.userData && o.userData.role === 'bg' && o.visible) { o.visible = false; hid.push(o); } });
396	      renderer.getClearColor(cc); const ca = renderer.getClearAlpha(); renderer.setClearColor(0x000000, 0);
397	      render0(scene, cam); renderer.setClearColor(cc, ca); scene.background = bg; for (const o of hid) o.visible = true;
398	    } else render0(scene, cam);
399	    if (V) cam.clearViewOffset();
400	  };
401	  return {
402	    renderer, O, out,
403	    compose() {
404	      O.finish();
405	      const m = CK.mode;
406	      if (m === 'all') { octx.drawImage(gl, 0, 0); octx.drawImage(ov, 0, 0); if (CK.dither >= 2 && !CK.on) darkDither(octx, W, H); return; }
407	      octx.clearRect(0, 0, W, H);
408	      if (m === 'graphics' || m === 'graphics3d' || m === 'notext') octx.drawImage(gl, 0, 0);
409	      octx.drawImage(ov, 0, 0);
410	    },
411	  };
412	}
413	
414	// dither CỐ ĐỊNH theo màn hình (như dither có thứ tự trước khi mã hoá): nhiễu tam giác (TPDF) ±4 mã (σ ≈ 1,6 mã) theo ô 2×2 px ở 1080
415	// (ô = res/540 px), cùng một mẫu ở mọi khung, chỉ cộng vào điểm ảnh tối (luma < 72). Bẻ các dải phẳng của gradient tối (sàn, sương, dải nền
416	// chrome) và SỐNG QUA hai lần mã hoá x264 (crf 16 → CBR 17M của master): khung P dự đoán đúng mẫu đứng yên nên không xoá nó. Đo (checks F08,
417	// banding_score, cửa sổ 70–84 s của Tập 5 ở 1080p, chuỗi mã hoá thật): không dither 62,9 %; nhiễu đổi theo khung ±4 mã 14,2 % (khung P mất
418	// nhiễu); mẫu cố định: xem BACKLOG F-6. Điểm sáng (chữ, vật) không đổi.
419	const DITHER = { amp: 4, lumaMax: 72, seed: 0x5EED1E };
420	let ditherField = null;
421	function darkDither(c, W, H) {
422	  const blk = Math.max(1, Math.round(H / 540)), nx = Math.ceil(W / blk), ny = Math.ceil(H / blk), A = DITHER.amp;
423	  if (!ditherField || ditherField.W !== W || ditherField.H !== H) {   // một mẫu cho cả phim (cùng hạt giống → mọi worker, mọi lần render như nhau)
424	    const f = new Int8Array(nx * ny); let s = DITHER.seed >>> 0;
425	    for (let i = 0; i < f.length; i++) { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; f[i] = Math.round(((s & 1023) + ((s >>> 10) & 1023) - 1023) / 1023 * A); }
426	    ditherField = { W, H, f };
427	  }
428	  const im = c.getImageData(0, 0, W, H), d = im.data, F = ditherField.f;
429	  for (let y = 0; y < H; y++) {
430	    const row = ((y / blk) | 0) * nx;
431	    for (let x = 0; x < W; x++) {
432	      const k = F[row + ((x / blk) | 0)]; if (!k) continue;
433	      const i = (y * W + x) * 4;
434	      if (((d[i] * 54 + d[i + 1] * 183 + d[i + 2] * 19) >> 8) >= DITHER.lumaMax) continue;
435	      d[i] = Math.min(255, Math.max(0, d[i] + k)); d[i + 1] = Math.min(255, Math.max(0, d[i + 1] + k)); d[i + 2] = Math.min(255, Math.max(0, d[i + 2] + k));
436	    }
437	  }
438	  c.putImageData(im, 0, 0);
439	}
