export function roundRect(ctx, x, y, w, h, r) { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }

// ------------------------------------------------------------------ máy quay: chụp / đặt lại trạng thái (freeze của trang kiểm)
const grabCam = (c) => ({ pos: c.position.toArray(), quat: c.quaternion.toArray(), fov: c.fov, aspect: c.aspect, near: c.near, far: c.far, zoom: c.zoom });
function applyCam(c, s) { c.position.fromArray(s.pos); c.quaternion.fromArray(s.quat); Object.assign(c, { fov: s.fov, aspect: s.aspect, near: s.near, far: s.far, zoom: s.zoom }); c.updateProjectionMatrix(); c.updateMatrixWorld(true); }
// vật 3D khai cho trang kiểm: object.userData.checks = {role, case?, year?, series?, …} → hình hộp bao chiếu lên màn hình (thiết kế 1920×1080)
const _b = new THREE.Box3(), _v = new THREE.Vector3();
function shapes3d(scene, cam) {
  const out = [];
  scene.traverse((o) => {
    const k = o.userData && o.userData.checks; if (!k || !o.visible) return;
    _b.setFromObject(o); if (_b.isEmpty()) return;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity, op = 0;
    for (let i = 0; i < 8; i++) { _v.set(i & 1 ? _b.max.x : _b.min.x, i & 2 ? _b.max.y : _b.min.y, i & 4 ? _b.max.z : _b.min.z).project(cam);
      const x = (_v.x + 1) * 960, y = (1 - _v.y) * 540; x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
    o.traverse((m) => { if (m.isMesh && m.visible) for (const q of [].concat(m.material)) op = Math.max(op, q.opacity ?? 1); });
    const box = [x0, y0, x1, y1].map(r1), key = k.key || o.name || o.uuid;
    out.push({ kind: 'shape', tag: 'mesh', role: 'mark', fill: null, stroke: null, ...k, box, opacity: +op.toFixed(3), key, sig: `${k.role || 'mark'}|${key}|${box.map(Math.round)}` });
  });
  return out;
}

// ------------------------------------------------------------------ khởi tạo trang chung: renderer WebGL + lớp phủ + canvas ra
export function Stage(res) {
  const V = CK.view && CK.view.orient === 'v' ? CK.view : null;
  const W = V ? Math.round(1080 * res / 1920) : Math.round(1920 * res / 1080), H = res;
  const vs = V ? (V.s || 1) : 1, cy = V ? (V.cy ?? (VZONE.y0 + VZONE.y1) / 2) : 0;
  const gl = document.createElement('canvas');
  // alpha: true — nền là scene.background (đục) nên khung render như cũ; lớp 'graphics' của trang kiểm cần nền trong suốt
  const renderer = new THREE.WebGLRenderer({ canvas: gl, antialias: true, preserveDrawingBuffer: true, powerPreference: 'low-power', alpha: true });
  renderer.setPixelRatio(1); renderer.setSize(W, H, false);
  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.05; renderer.outputColorSpace = THREE.SRGBColorSpace;
  const ov = document.createElement('canvas'), out = document.createElement('canvas'); out.width = W; out.height = H; document.body.appendChild(out);
  const O = Overlay(ov, res), octx = out.getContext('2d', CK.dither >= 2 ? { willReadFrequently: true } : undefined);
  const render0 = renderer.render.bind(renderer), cc = new THREE.Color();
  renderer.render = (scene, cam) => {
    const m = CK.mode;
    if (CK.dither >= 1) scene.traverse((o) => { if (o.material) for (const q of [].concat(o.material)) if (!q.dithering) { q.dithering = true; q.needsUpdate = true; } });
    if (CK.freezeCam) applyCam(cam, CK.freezeCam); else CK.lastCam = grabCam(cam);
    if (CK.on && m === 'all') CK.shapes3d = shapes3d(scene, cam);
    if (V) cam.setViewOffset(1920, 1080, 960 - 540 / vs, 540 - cy / vs, 1080 / vs, 1920 / vs);   // cửa sổ dọc của cùng khung thiết kế
    if (m === 'text' || m === 'glyph' || m === 'only' || m === 'graphics2d') { renderer.getClearColor(cc); const ca = renderer.getClearAlpha(); renderer.setClearColor(0x000000, 0); renderer.clear(); renderer.setClearColor(cc, ca); }
    else if (m === 'graphics' || m === 'graphics3d') {   // không nền: scene.background, sàn (userData.role 'bg')
      const bg = scene.background, hid = []; scene.background = null;
      scene.traverse((o) => { if (o.userData && o.userData.role === 'bg' && o.visible) { o.visible = false; hid.push(o); } });
      renderer.getClearColor(cc); const ca = renderer.getClearAlpha(); renderer.setClearColor(0x000000, 0);
      render0(scene, cam); renderer.setClearColor(cc, ca); scene.background = bg; for (const o of hid) o.visible = true;
    } else render0(scene, cam);
    if (V) cam.clearViewOffset();
  };
  return {
    renderer, O, out,
    compose() {
      O.finish();
      const m = CK.mode;
      if (m === 'all') { octx.drawImage(gl, 0, 0); octx.drawImage(ov, 0, 0); if (CK.dither >= 2 && !CK.on) darkDither(octx, W, H); return; }
      octx.clearRect(0, 0, W, H);
      if (m === 'graphics' || m === 'graphics3d' || m === 'notext') octx.drawImage(gl, 0, 0);
      octx.drawImage(ov, 0, 0);
    },
  };
}

// dither CỐ ĐỊNH theo màn hình (như dither có thứ tự trước khi mã hoá): nhiễu tam giác (TPDF) ±4 mã (σ ≈ 1,6 mã) theo ô 2×2 px ở 1080
// (ô = res/540 px), cùng một mẫu ở mọi khung, chỉ cộng vào điểm ảnh tối (luma < 72). Bẻ các dải phẳng của gradient tối (sàn, sương, dải nền
// chrome) và SỐNG QUA hai lần mã hoá x264 (crf 16 → CBR 17M của master): khung P dự đoán đúng mẫu đứng yên nên không xoá nó. Đo (checks F08,
// banding_score, cửa sổ 70–84 s của Tập 5 ở 1080p, chuỗi mã hoá thật): không dither 62,9 %; nhiễu đổi theo khung ±4 mã 14,2 % (khung P mất
// nhiễu); mẫu cố định: xem BACKLOG F-6. Điểm sáng (chữ, vật) không đổi.
const DITHER = { amp: 4, lumaMax: 72, seed: 0x5EED1E };
let ditherField = null;
function darkDither(c, W, H) {
  const blk = Math.max(1, Math.round(H / 540)), nx = Math.ceil(W / blk), ny = Math.ceil(H / blk), A = DITHER.amp;
  if (!ditherField || ditherField.W !== W || ditherField.H !== H) {   // một mẫu cho cả phim (cùng hạt giống → mọi worker, mọi lần render như nhau)
    const f = new Int8Array(nx * ny); let s = DITHER.seed >>> 0;
    for (let i = 0; i < f.length; i++) { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; f[i] = Math.round(((s & 1023) + ((s >>> 10) & 1023) - 1023) / 1023 * A); }
    ditherField = { W, H, f };
  }
  const im = c.getImageData(0, 0, W, H), d = im.data, F = ditherField.f;
  for (let y = 0; y < H; y++) {
    const row = ((y / blk) | 0) * nx;
    for (let x = 0; x < W; x++) {
      const k = F[row + ((x / blk) | 0)]; if (!k) continue;
      const i = (y * W + x) * 4;
      if (((d[i] * 54 + d[i + 1] * 183 + d[i + 2] * 19) >> 8) >= DITHER.lumaMax) continue;
      d[i] = Math.min(255, Math.max(0, d[i] + k)); d[i + 1] = Math.min(255, Math.max(0, d[i + 1] + k)); d[i + 2] = Math.min(255, Math.max(0, d[i + 2] + k));
    }
  }
  c.putImageData(im, 0, 0);
}

"""Nhà máy · SPINE v2 — đặc tả nhịp "một thế giới, hai chế độ máy quay" (D-010), rút từ hai đoạn chứng minh Mốc V.
Một nguồn duy nhất cho mọi lớp: lời (take), hình (chế độ, tư thế máy, cửa sổ động tác), âm dữ liệu, sfx, nhạc (bản đồ căng).
Mốc giờ CHỈ từ alignment của take ("@câu[:từ][$]"), đầu từ chỉnh theo năng lượng (onset.refine). Đoạn khai báo nhịp + động tác;
thư viện tính cửa sổ, âm của động tác, cảnh render (cache) và tự kiểm quy tắc 2/3/7. Quy tắc 1 kiểm trên nhật ký trang (verify_seg.py).

  from spine import Anchors, beats_from, window, move_sounds, shots_for, check_rules
  A = Anchors(words); beats = beats_from(B, A, lines); moves = [...window(...)...]; errs = check_rules(beats, moves, pad)
"""
import re


class Anchors:
    """words: [{w, s, e, sid}] (đã cộng vị trí take). at('@S01.2:twenty') = đầu từ; '@S01.2$' = cuối câu; '@S01.2' = từ đầu câu."""
    def __init__(self, words):
        self.words = words

    def at(self, ref):
        m = re.match(r'@(S\d\d\.\d)(?::([^$]+))?(\$)?$', ref)
        if not m:
            raise SystemExit(f'mốc sai: {ref!r}')
        sid, wd, e = m.groups(); ws = [w for w in self.words if w['sid'] == sid]
        if not ws:
            raise SystemExit(f'mốc {ref!r}: không có câu {sid} trong take')
        if e: return ws[-1]['e']
        if wd:
            hit = [w['s'] for w in ws if re.sub(r'[^\w-]', '', w['w']).lower().startswith(wd.lower())]
            if not hit: raise SystemExit(f'mốc {ref!r}: không có từ {wd!r} trong {sid}')
            return hit[0]
        return next(w['s'] for w in ws if not w['w'].startswith('['))


def words_from_timeline(timeline, scenes):
    """Lời của nhà máy (out/factory/timeline.json sau bước resolve) → words cho Anchors, giờ tính từ đầu cảnh đầu tiên của đoạn.
    Trả (words, t0 của đoạn trong tập, độ dài đoạn). Đoạn thế giới của một tập dùng đúng take đã dựng, không sinh lại giọng."""
    sc = [s for s in timeline['scenes'] if s['id'] in scenes]
    if [s['id'] for s in sc] != list(scenes): raise SystemExit(f'cảnh {scenes} không liền/không có trong timeline')
    t0, t1 = sc[0]['start'], sc[-1]['start'] + sc[-1]['dur']
    ws = [{'w': w['w'], 's': round(w['s'] - t0, 3), 'e': round(w['e'] - t0, 3), 'sid': w['sid']} for w in timeline['words'] if t0 <= w['s'] < t1]
    return ws, t0, round(t1 - t0, 4)


def beats_from(B, A, lines):
    """B: [(id, sid, mode world|chart, ý, hình, {cue: '@…'}, [âm], căng 0–1, cảm xúc, chuyển)] → nhịp có t0/t1/cues (giây)."""
    out = []
    for bid, sid, mode, idea, visual, cues, sound, ten, emo, nxt in B:
        if mode not in ('world', 'chart'): raise SystemExit(f'{bid}: chế độ {mode!r} (world|chart)')
        out.append({'id': bid, 'sid': sid, 'mode': mode, 'idea': idea, 'visual': visual, 'line': lines[sid], 'sound': sound, 'music': ten,
                    'emotion': emo, 'next': nxt, 't0': A.at('@' + sid), 't1': A.at('@' + sid + '$'), 'cues': {k: A.at(v) for k, v in cues.items()}})
    return out


def cue_list(beats):
    return sorted((t, f"{b['id']}.{k}") for b in beats for k, t in b['cues'].items())


def window(after, before, dur, pad=0.25, late=False, start=None, eps=0.0):
    """Cửa sổ động tác giữa hai từ khoá: bắt đầu sau after+pad, kết thúc trước before−pad, dài tối đa dur.
    late: sát từ khoá sau; start: neo vào một mốc (vd đầu câu); eps: lùi mép phải thêm (Tập 5 dùng 0,01)."""
    a, b = after + pad, before - pad
    if b - a < 0.6: raise SystemExit(f'cửa sổ quá ngắn giữa {after} và {before}')
    b -= eps
    t0 = max(a, b - dur) if late else max(a, (a + b) / 2 - dur / 2)
    if start is not None: t0 = min(max(a, start), b - 0.6)
    return [round(t0, 3), round(min(b, t0 + dur), 3)]


VERBS = ('push', 'pull', 'pan', 'mode')
# F-1 (BACKLOG): kiểu chuyển chế độ, cờ opt-in trên động tác 'mode': không khai = 'dissolve' (hành vi cũ, điểm ảnh không đổi);
# 'fly' = máy quay đi thật (core.js flyPose: đường cong qua tư thế 'via', dolly-zoom tới tiêu cự dài, chartW chỉ dâng khi đã chính diện).
# Cửa sổ, âm, cảnh render KHÔNG phụ thuộc kiểu → quy tắc 2/3 giữ nguyên.
MODE_STYLES = ('dissolve', 'fly')


def with_style(move, style=None, via=None):
    """Gắn kiểu chuyển chế độ vào một động tác (không đổi t0/t1/âm). style None/'dissolve' → trả nguyên động tác (spine.json không đổi)."""
    if style in (None, 'dissolve'):
        return move
    if style not in MODE_STYLES or move['verb'] != 'mode':
        raise SystemExit(f'F-1: kiểu {style!r} chỉ cho động tác mode, một trong {MODE_STYLES}')
    return {**move, 'style': style, **({'via': via} if via else {})}


def move_sounds(moves, gain=lambda m: 1.0):
    """Quy tắc 3: mọi động tác có âm (sound của nó, dài bằng cửa sổ); chỉ đổi chế độ mới có tiếng chạm ở cuối."""
    ev = []
    for m in moves:
        ev.append({'t': m['t0'], 'kind': m['sound'], 'dur': round(m['t1'] - m['t0'], 3), 'gain': gain(m)})
        if m['verb'] == 'mode': ev.append({'t': m['t1'], 'kind': 'land', 'mode': True})
    return ev


def shots_for(moves, total):
    """Quy tắc 8: cảnh render (đơn vị cache) = ranh giới ở đầu mỗi động tác máy quay."""
    cuts = [0] + [m['t0'] for m in moves] + [total]
    return [{'id': f's{i}', 't0': round(a, 3), 't1': round(b, 3)} for i, (a, b) in enumerate(zip(cuts, cuts[1:]))]


def check_rules(beats, moves, pad, rule3=True):
    """Quy tắc 2 (máy đứng yên ± pad quanh mọi từ khoá), 3 (động tác hữu hạn, có lý do + âm), 7 (5 s đầu ở chế độ thế giới)."""
    errs, C = [], cue_list(beats)
    for m in moves:
        for t, name in C:
            if m['t0'] - pad < t < m['t1'] + pad: errs.append(f'quy tắc 2: từ khoá {name} @{t} trong cửa sổ máy quay {m["verb"]} {m["t0"]}–{m["t1"]}')
        if rule3 and (not m.get('reason') or not m.get('sound') or m['verb'] not in VERBS):
            errs.append(f'quy tắc 3: động tác {m} thiếu lý do/âm hoặc động từ ngoài {VERBS}')
        if m.get('style', 'dissolve') not in MODE_STYLES or (m.get('style') == 'fly' and m['verb'] != 'mode'):
            errs.append(f'F-1: kiểu chuyển {m.get("style")!r} không hợp lệ cho {m["verb"]} (chỉ mode, {MODE_STYLES})')
    if beats[0]['mode'] != 'world' or any(m['verb'] == 'mode' and m['t0'] < 5.0 for m in moves):
        errs.append('quy tắc 7: 5 s đầu phải ở chế độ thế giới')
    return errs

"""Nhà máy · DỰNG MỘT ĐOẠN THẾ GIỚI 3D bằng một lệnh (D-010; quy trình hai đoạn chứng minh Mốc V).

  python3 toolkit/factory/world/build_seg.py <thư mục đoạn> [--res 540|1080] [--out <file.mp4>] [--workers 3] [--music code|<wav>]

Thư mục đoạn chứa: spine.py (đặc tả nhịp, dùng toolkit/factory/world/spine.py) + scene.js (dùng lib3d.js/core.js) [+ dữ liệu].
Các bước (mỗi bước dừng cả lệnh nếu trượt):
  lint    toolkit/tests/comment_guard.py trên thư mục đoạn + thư viện: chú thích nuốt mã (lint_comments + mẫu mở rộng) + node --check / py_compile
  spine   python3 <đoạn>/spine.py → spine.json; thoát ≠ 0 = vi phạm quy tắc 2/3/7
  render  render_shots.js theo cảnh có cache (chỉ cảnh đổi mới render; chạy lại = resume); lỗi trang = dừng
  audio   audio.py: lời + nhạc theo bản đồ căng + âm dữ liệu + sfx từ spine.events → mix.wav (−14 LUFS)
  mux     hình + tiếng → <out>
  verify  verify_seg.py: quy tắc 1/2/3, cắt cứng, tỉ lệ chế độ, C14 (bản 1080p), F-2 (mật độ sfx, nhãn đè nhau) → <out>.verify.json;
          quy tắc 1/2/3, cắt cứng, C14 hoặc F-2 cấp BLOCK trượt = thoát 1 (F-2 WARN chỉ báo)
Báo cáo giờ render thật (wall, s/giây phim) trong <out>.build.json (quy tắc 8: "báo giờ render và token thực").
An toàn (tổng kết Tập 5 mục 12; cine-lab #67, #70): trước khi dựng kiểm không còn build/render nào khác (`guard.py`, thoát 3 nếu còn);
mọi tệp ra dựng trong thư mục tạm `<thư mục ra>/.staging-<tên>-<pid>/`, CHỈ thay bản cũ khi cả 6 bước đạt. Trượt → bản cũ giữ nguyên,
báo cáo ở `<out>.build.failed.json`, thư mục tạm giữ lại để xem.
Đồng bộ lời–hình bằng ASR (sync_audit.py) chạy riêng vì cần faster-whisper.
"""
import json, os, shutil, subprocess, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..', '..', '..'))
sys.path.insert(0, HERE)
sys.dont_write_bytecode = True
import lint_comments  # noqa: E402
sys.path.insert(0, os.path.dirname(HERE))
import guard  # noqa: E402
sys.path.insert(0, os.path.join(ROOT, 'toolkit', 'tests'))
import comment_guard  # noqa: E402


def arg(k, d=None):
    return sys.argv[sys.argv.index(k) + 1] if k in sys.argv else d


def run(cmd, **kw):
    r = subprocess.run(cmd, cwd=ROOT, text=True, capture_output=True, **kw)
    if r.returncode:
        print(r.stdout[-3000:], r.stderr[-3000:])
    return r


def promote(stage, final_dir, base):
    """Đưa mọi tệp/thư mục `base*` từ thư mục tạm sang chỗ thật (thay bản cũ); chỉ gọi khi mọi bước đạt."""
    for f in sorted(os.listdir(stage)):
        if not f.startswith(base):
            continue
        src, dst = os.path.join(stage, f), os.path.join(final_dir, f)
        if os.path.isdir(src) and os.path.isdir(dst):
            old = dst + f'.old-{os.getpid()}'
            os.replace(dst, old); os.replace(src, dst); shutil.rmtree(old, ignore_errors=True)
        else:
            os.replace(src, dst)
    shutil.rmtree(stage, ignore_errors=True)


def main():
    guard.assert_idle('build_seg')
    seg = os.path.relpath(os.path.abspath(sys.argv[1]), ROOT)
    res = int(arg('--res', 540))
    final = os.path.abspath(arg('--out', os.path.join(ROOT, seg, '..', '..', 'work', 'world', f'{os.path.basename(seg)}-{res}.mp4')))
    base = os.path.basename(final)[:-len('.mp4')]
    stage = os.path.join(os.path.dirname(final), f'.staging-{base}-{os.getpid()}')
    os.makedirs(stage, exist_ok=True)
    out = os.path.join(stage, os.path.basename(final))   # mọi bước ghi vào thư mục tạm
    rep, T = {'segment': seg, 'res': res, 'out': os.path.relpath(final, ROOT), 'steps': {}}, time.time()

    def step(name, fn):
        t = time.time(); ok, info = fn(); rep['steps'][name] = {'seconds': round(time.time() - t, 1), 'ok': ok, **(info or {})}
        print(f'[{name}] {"OK" if ok else "TRƯỢT"} {rep["steps"][name]["seconds"]} s', flush=True)
        if not ok:
            rep['staging'] = os.path.relpath(stage, ROOT)
            json.dump(rep, open(final + '.build.failed.json', 'w'), indent=1, ensure_ascii=False)
            raise SystemExit(f'build_seg: dừng ở bước {name}; bản cũ giữ nguyên, thư mục tạm {os.path.relpath(stage, ROOT)}')

    def lint():   # F-4 + tổng kết Tập 5 mục 13 (cine-lab #42, #76): chú thích giữa dòng nuốt mã + node --check / py_compile
        bad, n = comment_guard.check([os.path.join(ROOT, seg), HERE])
        return not bad, {'problems': bad, 'files': n}

    def spine():
        r = run([sys.executable, os.path.join(seg, 'spine.py')])
        return r.returncode == 0, {'stdout': r.stdout.strip().splitlines()[-1:] }

    def render():
        env = {**os.environ, 'NODE_PATH': subprocess.run(['npm', 'root', '-g'], capture_output=True, text=True).stdout.strip()}
        pic = out.replace('.mp4', '.picture.mp4')
        r = run(['node', os.path.join(HERE, 'render_shots.js'), seg, str(res), pic, '--workers', arg('--workers', '3')], env=env)
        st = json.load(open(pic + '.render.json')) if r.returncode == 0 else {}
        return r.returncode == 0, {k: st.get(k) for k in ('shots', 'rendered', 'cached', 'wall_s', 'film_s', 'wall_per_film_s_rendered', 'cores')}

    def audio():
        r = run([sys.executable, os.path.join(HERE, 'audio.py'), out.replace('.mp4', '.audio'), '--spine', os.path.join(seg, 'spine.json'),
                 '--music', arg('--music', 'code')])
        return r.returncode == 0, None

    def mux():
        pic, mix = out.replace('.mp4', '.picture.mp4'), os.path.join(out.replace('.mp4', '.audio'), 'mix.wav')
        r = run(['ffmpeg', '-y', '-loglevel', 'error', '-i', pic, '-i', mix, '-map', '0:v', '-map', '1:a', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '256k',
                 out])   # F-13 (Tập 6 C4): không -shortest — với AAC nó cắt 2–4 khung cuối (1537 → 1535) và splice dừng; mix.wav dài đúng bằng hình
        if r.returncode == 0:   # nhật ký trang đi theo video (verify_seg đọc <video>.log.json)
            os.replace(pic.replace('.mp4', '.log.json'), out.replace('.mp4', '.log.json'))
            if os.path.exists(pic.replace('.mp4', '.cam.json')):   # máy quay từng khung → out/camera.json của tập (artefacts.py)
                os.replace(pic.replace('.mp4', '.cam.json'), out.replace('.mp4', '.cam.json'))
        return r.returncode == 0, None

    def verify():
        vj = out + '.verify.json'
        r = run([sys.executable, os.path.join(HERE, 'verify_seg.py'), os.path.join(ROOT, seg), out, vj])
        if r.returncode:
            return False, None
        v = json.load(open(vj))
        fail = {'rule1': v['rule1']['violations'], 'rule2': len(v['rule2']['camera_moving_at_keyword']), 'rule3': len(v['rule3']['missing_reason_or_sound']),
                'hard_cuts': len(v['cuts']['hard_cuts']), 'first_5s_world': v['modes']['first_5s_world']}
        c14 = v['C14'].get('violations')
        f2 = v['F2']   # F-2: BLOCK (sfx che từ khoá / nhãn đè nhau ở trạng thái đọc) dừng build; WARN chỉ báo
        for lv in ('block', 'warn'):
            for m in f2[lv]: print(f'  F-2 {lv.upper()}: {m}')
        ok = not (fail['rule1'] or fail['rule2'] or fail['rule3'] or fail['hard_cuts']) and fail['first_5s_world'] and not c14 and f2['level'] != 'BLOCK'
        return ok, {**fail, 'C14': v['C14'], 'modes': v['modes'], 'F2': {**f2['summary'], 'block': f2['block'], 'warn': f2['warn']}}

    for name, fn in (('lint', lint), ('spine', spine), ('render', render), ('audio', audio), ('mux', mux), ('verify', verify)):
        step(name, fn)
    rep['total_seconds'] = round(time.time() - T, 1)
    json.dump(rep, open(out + '.build.json', 'w'), indent=1, ensure_ascii=False)
    promote(stage, os.path.dirname(final), base)
    if os.path.exists(final + '.build.failed.json'):
        os.remove(final + '.build.failed.json')
    print(f'build_seg: {rep["total_seconds"]} s → {os.path.relpath(final, ROOT)}')


if __name__ == '__main__':
    main()

